// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Adopt an existing (un-spawned) session
	// (POST /api/v1/adopt)
	AdoptSession(w http.ResponseWriter, r *http.Request)
	// Live approval queue
	// (GET /api/v1/approvals)
	ListApprovals(w http.ResponseWriter, r *http.Request)
	// Read the live auto-approve policy
	// (GET /api/v1/auto-approve/policy)
	GetAutoApprovePolicy(w http.ResponseWriter, r *http.Request)
	// Replace the live auto-approve policy
	// (PUT /api/v1/auto-approve/policy)
	SetAutoApprovePolicy(w http.ResponseWriter, r *http.Request)
	// Run the project's .warden/check.yml command(s)
	// (POST /api/v1/check)
	RunCheck(w http.ResponseWriter, r *http.Request)
	// Per-agent CI + branch-vs-main status
	// (GET /api/v1/collab/branches)
	GetBranchStatus(w http.ResponseWriter, r *http.Request)
	// Current inter-agent file conflicts
	// (GET /api/v1/collab/conflicts)
	GetConflicts(w http.ResponseWriter, r *http.Request)
	// List shared-context entries
	// (GET /api/v1/context)
	ListContext(w http.ResponseWriter, r *http.Request, params ListContextParams)
	// Delete a shared-context entry
	// (DELETE /api/v1/context/{key})
	DeleteContext(w http.ResponseWriter, r *http.Request, key CtxKey)
	// Read a shared-context entry
	// (GET /api/v1/context/{key})
	GetContext(w http.ResponseWriter, r *http.Request, key CtxKey)
	// Write a shared-context entry
	// (PUT /api/v1/context/{key})
	SetContext(w http.ResponseWriter, r *http.Request, key CtxKey)
	// Atomically append to a shared-context entry
	// (POST /api/v1/context/{key}/append)
	AppendContext(w http.ResponseWriter, r *http.Request, key CtxKey)
	// Compare-and-swap a shared-context entry
	// (POST /api/v1/context/{key}/cas)
	CasContext(w http.ResponseWriter, r *http.Request, key CtxKey)
	// Ingest a Claude hook event
	// (POST /api/v1/events)
	IngestEvent(w http.ResponseWriter, r *http.Request)
	// List immediate subdirectories
	// (GET /api/v1/fs/dirs)
	ListDirs(w http.ResponseWriter, r *http.Request, params ListDirsParams)
	// Stage + commit a worktree (rail-enforcing)
	// (POST /api/v1/git/commit)
	GitCommit(w http.ResponseWriter, r *http.Request)
	// Push a worktree's branch to origin (protected-branch refusal)
	// (POST /api/v1/git/push)
	GitPush(w http.ResponseWriter, r *http.Request)
	// Rebase a worktree's branch onto origin/base
	// (POST /api/v1/git/sync)
	GitSync(w http.ResponseWriter, r *http.Request)
	// Browse the archived (closed) session store
	// (GET /api/v1/history)
	ListHistory(w http.ResponseWriter, r *http.Request, params ListHistoryParams)
	// Isolation guard verdict for a file-mutating tool call
	// (POST /api/v1/hooks/guard)
	GuardHook(w http.ResponseWriter, r *http.Request)
	// Import session records from an export envelope
	// (POST /api/v1/import)
	ImportSessions(w http.ResponseWriter, r *http.Request, params ImportSessionsParams)
	// Recent message traffic across all inboxes
	// (GET /api/v1/messages)
	ListRecentMessages(w http.ResponseWriter, r *http.Request, params ListRecentMessagesParams)
	// Live resource snapshot
	// (GET /api/v1/metrics)
	GetMetrics(w http.ResponseWriter, r *http.Request)
	// Recorded metrics samples or per-agent summaries
	// (GET /api/v1/metrics/history)
	GetMetricsHistory(w http.ResponseWriter, r *http.Request, params GetMetricsHistoryParams)
	// List pipelines
	// (GET /api/v1/pipelines)
	ListPipelines(w http.ResponseWriter, r *http.Request)
	// Create a pipeline from a YAML spec
	// (POST /api/v1/pipelines)
	CreatePipeline(w http.ResponseWriter, r *http.Request)
	// Delete a pipeline
	// (DELETE /api/v1/pipelines/{pid})
	DeletePipeline(w http.ResponseWriter, r *http.Request, pid PipelineId)
	// Show one pipeline
	// (GET /api/v1/pipelines/{pid})
	GetPipeline(w http.ResponseWriter, r *http.Request, pid PipelineId)
	// Cancel a pipeline
	// (POST /api/v1/pipelines/{pid}/cancel)
	CancelPipeline(w http.ResponseWriter, r *http.Request, pid PipelineId)
	// Edit a pending job's prompt and/or handoff
	// (POST /api/v1/pipelines/{pid}/jobs/{job}/edit)
	EditPipelineJob(w http.ResponseWriter, r *http.Request, pid PipelineId, job JobId)
	// Emit a job's output (commit work + fan out downstream)
	// (POST /api/v1/pipelines/{pid}/jobs/{job}/emit)
	EmitPipelineJob(w http.ResponseWriter, r *http.Request, pid PipelineId, job JobId)
	// Retry a failed / needs-attention job
	// (POST /api/v1/pipelines/{pid}/jobs/{job}/retry)
	RetryPipelineJob(w http.ResponseWriter, r *http.Request, pid PipelineId, job JobId)
	// Pause a pipeline (halt new spawns)
	// (POST /api/v1/pipelines/{pid}/pause)
	PausePipeline(w http.ResponseWriter, r *http.Request, pid PipelineId)
	// Resume a paused pipeline
	// (POST /api/v1/pipelines/{pid}/resume)
	ResumePipeline(w http.ResponseWriter, r *http.Request, pid PipelineId)
	// Start a pipeline (reconcile + spawn ready jobs)
	// (POST /api/v1/pipelines/{pid}/start)
	StartPipeline(w http.ResponseWriter, r *http.Request, pid PipelineId)
	// Memory-pressure + spawn-gate status
	// (GET /api/v1/pressure)
	GetPressure(w http.ResponseWriter, r *http.Request)
	// Reclaim orphan worktrees
	// (POST /api/v1/prune)
	PruneWorktrees(w http.ResponseWriter, r *http.Request)
	// Revive archived agent records whose tmux session is still alive
	// (POST /api/v1/recover)
	RecoverAgents(w http.ResponseWriter, r *http.Request)
	// List the built-in agent roles
	// (GET /api/v1/roles)
	ListRoles(w http.ResponseWriter, r *http.Request)
	// Aggregated token-savings summary
	// (GET /api/v1/savings)
	GetSavings(w http.ResponseWriter, r *http.Request, params GetSavingsParams)
	// List schedules
	// (GET /api/v1/schedules)
	ListSchedules(w http.ResponseWriter, r *http.Request)
	// Create a recurring (cron) or single-shot (at) schedule
	// (POST /api/v1/schedules)
	CreateSchedule(w http.ResponseWriter, r *http.Request)
	// Delete a schedule
	// (DELETE /api/v1/schedules/{id})
	DeleteSchedule(w http.ResponseWriter, r *http.Request, id ScheduleId)
	// Full-text search across sessions
	// (GET /api/v1/search)
	Search(w http.ResponseWriter, r *http.Request, params SearchParams)
	// List active sessions
	// (GET /api/v1/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// Get one session by id or name
	// (GET /api/v1/sessions/{id})
	GetSession(w http.ResponseWriter, r *http.Request, id SessionId)
	// Answer a recognized permission prompt
	// (POST /api/v1/sessions/{id}/approve)
	ApproveSession(w http.ResponseWriter, r *http.Request, id SessionId)
	// Toggle auto-approve for an agent
	// (PATCH /api/v1/sessions/{id}/auto-approve)
	SetAutoApprove(w http.ResponseWriter, r *http.Request, id SessionId)
	// Open a GitHub PR for the agent's branch
	// (POST /api/v1/sessions/{id}/create-pr)
	CreatePR(w http.ResponseWriter, r *http.Request, id SessionId)
	// Delete a session record
	// (POST /api/v1/sessions/{id}/delete)
	DeleteSession(w http.ResponseWriter, r *http.Request, id SessionId)
	// Completion digest for an agent
	// (GET /api/v1/sessions/{id}/digest)
	GetDigest(w http.ResponseWriter, r *http.Request, id SessionId)
	// Set an agent's force-compact override (on / off / inherit)
	// (PATCH /api/v1/sessions/{id}/force-compact)
	SetForceCompact(w http.ResponseWriter, r *http.Request, id SessionId)
	// Send text input to an agent's pane
	// (POST /api/v1/sessions/{id}/input)
	SendInput(w http.ResponseWriter, r *http.Request, id SessionId)
	// Read an agent's inbox
	// (GET /api/v1/sessions/{id}/messages)
	GetInbox(w http.ResponseWriter, r *http.Request, id SessionId, params GetInboxParams)
	// Send a directed message to an agent
	// (POST /api/v1/sessions/{id}/messages)
	SendMessage(w http.ResponseWriter, r *http.Request, id SessionId)
	// Long-poll for a message
	// (GET /api/v1/sessions/{id}/messages/wait)
	WaitForMessage(w http.ResponseWriter, r *http.Request, id SessionId, params WaitForMessageParams)
	// Rename an agent
	// (PATCH /api/v1/sessions/{id}/name)
	SetName(w http.ResponseWriter, r *http.Request, id SessionId)
	// Read recent pane output
	// (GET /api/v1/sessions/{id}/output)
	GetOutput(w http.ResponseWriter, r *http.Request, id SessionId, params GetOutputParams)
	// Set an agent's permission mode
	// (PATCH /api/v1/sessions/{id}/permission-mode)
	SetPermissionMode(w http.ResponseWriter, r *http.Request, id SessionId)
	// Remove the session's git worktree + branch
	// (POST /api/v1/sessions/{id}/remove-worktree)
	RemoveWorktree(w http.ResponseWriter, r *http.Request, id SessionId)
	// Restore (re-create + resume) a lost session
	// (POST /api/v1/sessions/{id}/restore)
	RestoreSession(w http.ResponseWriter, r *http.Request, id SessionId)
	// Set an agent's built-in role
	// (PATCH /api/v1/sessions/{id}/role)
	SetRole(w http.ResponseWriter, r *http.Request, id SessionId)
	// Terminate an agent
	// (POST /api/v1/sessions/{id}/terminate)
	TerminateSession(w http.ResponseWriter, r *http.Request, id SessionId)
	// List snapshots
	// (GET /api/v1/snapshots)
	ListSnapshots(w http.ResponseWriter, r *http.Request, params ListSnapshotsParams)
	// Capture a worktree + transcript snapshot
	// (POST /api/v1/snapshots)
	CreateSnapshot(w http.ResponseWriter, r *http.Request)
	// Restore a snapshot onto its recorded worktree
	// (POST /api/v1/snapshots/{id}/restore)
	RestoreSnapshot(w http.ResponseWriter, r *http.Request, id SnapshotId)
	// Spawn a new agent
	// (POST /api/v1/spawn)
	SpawnAgent(w http.ResponseWriter, r *http.Request)
	// Per-agent / per-repo / per-day cost rollup
	// (GET /api/v1/spend)
	GetSpend(w http.ResponseWriter, r *http.Request)
	// List a repo's worktrees
	// (GET /api/v1/worktrees)
	ListWorktrees(w http.ResponseWriter, r *http.Request, params ListWorktreesParams)
}

